<?php
namespace App\Entity;
use Doctrine\Common\Collections\ArrayCollection; use Doctrine\Common\Collections\Collection; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] class Ecurie { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\Column(length:150,unique:true)] private string $nom=''; #[ORM\ManyToOne(inversedBy:'ecuries')] #[ORM\JoinColumn(nullable:false)] private ?Division $division=null; #[ORM\Column(type:'float')] private float $etatVoiture=100.0; #[ORM\Column] private int $nombreChampionnatConstructeur=0; #[ORM\Column] private bool $active=true; #[ORM\OneToMany(mappedBy:'ecurie',targetEntity:Engagement::class)] private Collection $engagements; public function __construct(){$this->engagements=new ArrayCollection();} public function getId():?int{return $this->id;} public function getNom():string{return $this->nom;} public function setNom(string $v):self{$this->nom=$v;return $this;} public function getDivision():?Division{return $this->division;} public function setDivision(?Division $v):self{$this->division=$v;return $this;} public function getEtatVoiture():float{return $this->etatVoiture;} public function setEtatVoiture(float $v):self{$this->etatVoiture=$v;return $this;} public function getNombreChampionnatConstructeur():int{return $this->nombreChampionnatConstructeur;} public function setNombreChampionnatConstructeur(int $v):self{$this->nombreChampionnatConstructeur=$v;return $this;} public function isActive():bool{return $this->active;} public function setActive(bool $v):self{$this->active=$v;return $this;} public function getEngagements():Collection{return $this->engagements;} }
